      "link_oficial": "https://agenciabrasil.ebc.com.br/politica/noticia/2026-10/segundo-turno-saiba-como-consultar-local-de-votacao-para-domingo",
      "categoria": "Política & Leis",
      "fonte": "Agência Brasil / EBC (Empresa Brasil de Comunicação)",
